// Package workspace guards against sandboxing directories that cannot be
// safely bind-mounted (the home directory or filesystem root) by redirecting
// to a dated workspace under ~/asylum-workspace/.
package workspace

import (
	"bufio"
	"bytes"
	"math/rand"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/inventage-ai/asylum/assets"
)

var words = parseWords(assets.WorkspaceWords)

// namePattern matches the names generated by name, so hand-made directories
// under ~/asylum-workspace/ are never picked for reuse.
var namePattern = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}(-[a-z]+){3}$`)

// Outcome reports what Resolve did with the project directory.
type Outcome int

const (
	Unchanged Outcome = iota // safe directory, used as-is
	Fresh                    // new workspace created
	Reused                   // newest existing workspace reused
)

func parseWords(data []byte) []string {
	var out []string
	sc := bufio.NewScanner(bytes.NewReader(data))
	for sc.Scan() {
		if w := strings.TrimSpace(sc.Text()); w != "" {
			out = append(out, w)
		}
	}
	return out
}

// unsafe reports whether dir cannot be safely sandboxed: the exact home
// directory or the filesystem root. Subdirectories of home are safe.
func unsafe(dir, home string) bool {
	dir = filepath.Clean(dir)
	return dir == filepath.Clean(home) || dir == string(filepath.Separator)
}

func name(date string, r *rand.Rand) string {
	w := func() string { return words[r.Intn(len(words))] }
	return date + "-" + w() + "-" + w() + "-" + w()
}

// Resolve returns projectDir unchanged when it is safe to sandbox. When it is
// the home directory or filesystem root, it redirects to a workspace under
// ~/asylum-workspace/. With reuse set, that is the most recently modified
// existing workspace. Otherwise, or when none exists, it creates a fresh
// <YYYY-MM-DD>-<three-words>/ directory.
func Resolve(projectDir, home string, reuse bool) (string, Outcome, error) {
	if !unsafe(projectDir, home) {
		return projectDir, Unchanged, nil
	}
	base := filepath.Join(home, "asylum-workspace")
	if reuse {
		dir, err := newest(base)
		if err != nil {
			return "", Unchanged, err
		}
		if dir != "" {
			return dir, Reused, nil
		}
	}
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	dir, err := create(base, time.Now().Format("2006-01-02"), r)
	if err != nil {
		return "", Unchanged, err
	}
	return dir, Fresh, nil
}

// newest returns the most recently modified generated workspace under base,
// or "" when there is none.
func newest(base string) (string, error) {
	entries, err := os.ReadDir(base)
	if os.IsNotExist(err) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	var best string
	var bestTime time.Time
	for _, e := range entries {
		if !e.IsDir() || !namePattern.MatchString(e.Name()) {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if best == "" || info.ModTime().After(bestTime) {
			best, bestTime = filepath.Join(base, e.Name()), info.ModTime()
		}
	}
	return best, nil
}

func create(base, date string, r *rand.Rand) (string, error) {
	for {
		dir := filepath.Join(base, name(date, r))
		_, err := os.Stat(dir)
		if err == nil {
			continue // collision — re-roll the words
		}
		if !os.IsNotExist(err) {
			return "", err
		}
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return "", err
		}
		return dir, nil
	}
}
